import{_ as r,o as e,c as a,ai as d}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"IIoT 工业物联网监控系统","description":"","frontmatter":{},"headers":[],"relativePath":"instances/industrial/iiot.md","filePath":"instances/industrial/iiot.md"}'),s={name:"instances/industrial/iiot.md"},i={viewBox:"0 0 880 236",width:"100%",style:{"max-width":"100%",height:"auto",display:"block"},xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"IIoT 功能架构图"},o={viewBox:"0 0 880 292",width:"100%",style:{"max-width":"100%",height:"auto",display:"block"},xmlns:"http://www.w3.org/2000/svg",role:"img","aria-label":"IIoT 分层结构图"};function c(n,t,l,h,p,v){return e(),a("div",null,[t[2]||(t[2]=d('<h1 id="iiot-工业物联网监控系统" tabindex="-1">IIoT 工业物联网监控系统 <a class="header-anchor" href="#iiot-工业物联网监控系统" aria-label="Permalink to “IIoT 工业物联网监控系统”">​</a></h1><div class="sys-hero"><div class="sys-hero__eyebrow">02 工业数字化 · 优先级 2 / 3</div><div class="sys-hero__badges"><span class="sys-badge sys-badge--ok">✅ P0 已收口（MQTT · Modbus · 规则告警 · 看板 · P0-15 E2E）</span><span class="sys-badge">Java 21 · Spring Boot 3</span><span class="sys-badge">:18089 · openbiz_iiot</span><span class="sys-badge">一键 verify-p0-15 · E2E-RESULT.txt</span></div><p class="sys-hero__pitch">设备不再靠人喊：PLC 与仪表的状态、工艺参数、告警自动收上来，断线补传不丢数，故障先于停线被发现</p></div><blockquote><p>诚实边界：MQTT / Modbus TCP、点位、攒批幂等、规则告警（持续/迟滞/收敛）、通知 outbox、分区聚合、看板、P0-15 一键验收都已落地。<strong>P1-16 协议</strong>：Modbus RTU（CRC + RTU-over-TCP）、S7 SoftPLC（ISO-on-TCP Read DB）、OPC-UA Soft（OBUA 演示帧，非完整 UA Binary）均可本地闭环；真 RS485 / 真 PLC / 完整 <code>opc.tcp</code> 仍需硬件或 Milo/Kepware。<strong>未做</strong>：边缘网关、TDengine、OEE、真机 TLS；断库补传与 20 万队列溢出（设计用例 4/5）在一键脚本里显式 SKIP。</p></blockquote><h2 id="业务场景" tabindex="-1">业务场景 <a class="header-anchor" href="#业务场景" aria-label="Permalink to “业务场景”">​</a></h2><p><strong>一家什么样的厂</strong>：设备品牌杂、协议杂——PLC、仪表、变频器、AGV 各说各话。数据其实一直在设备里，但没人取；故障靠操作工喊人，停机原因事后靠回忆复盘。</p><table tabindex="0"><thead><tr><th>角色</th><th>在系统里做什么</th><th>没有系统时的样子</th></tr></thead><tbody><tr><td>设备工程师</td><td>配点位（设备 × 指标 × 采集周期）</td><td>想看一次数据要拎笔记本去现场连 PLC</td></tr><tr><td>班组长</td><td>看看板状态灯与活动告警</td><td>挨台设备看指示灯，靠经验判断正不正常</td></tr><tr><td>值班调度</td><td>收告警、认领、处理、关单</td><td>电话通知，谁处理了、处理到哪没人知道</td></tr><tr><td>设备主管</td><td>看历史曲线与故障频次</td><td>停机了才复盘，没有数据只能凭印象</td></tr></tbody></table><p><strong>这段业务真正难的地方是「采得上、存得下、报得准」三件事同时成立</strong>：采集端一断就丢数，高频写入一攒就把业务库拖死，告警一多就没人看——三个问题互相牵制，任何一环偷懒，看板上的数字就没人敢信。</p><p>三条落到业务上的硬约束：</p><ul><li><strong>采集线程不写库</strong>：写库慢不拖采集，断线进本地缓冲，恢复后按时间序补传，缺口显式标记</li><li><strong>告警只由规则产生</strong>：阈值 + 持续时长 + 迟滞恢复 + 窗口收敛，不允许接口手工造告警</li><li><strong>遥测只追加</strong>：明细表不提供改删，纠错靠补新点 + 缺口标记，历史永远查得回</li></ul><h2 id="功能架构" tabindex="-1">功能架构 <a class="header-anchor" href="#功能架构" aria-label="Permalink to “功能架构”">​</a></h2>',10)),(e(),a("svg",i,[...t[0]||(t[0]=[d('<rect x="0" y="0" width="880" height="236" rx="14" fill="var(--vp-c-bg-soft)"></rect><text x="124" y="40" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">现场层</text><rect x="140" y="16" width="232" height="38" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="256" y="40" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">PLC · 传感器</text><rect x="384" y="16" width="232" height="38" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="500" y="40" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">仪表 · 变频器</text><rect x="628" y="16" width="232" height="38" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="744" y="40" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">AGV · 立库</text><text x="124" y="98" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">接入层</text><rect x="140" y="74" width="232" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="256" y="98" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">MQTT 订阅</text><rect x="384" y="74" width="232" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="500" y="98" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">Modbus 轮询</text><rect x="628" y="74" width="232" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="744" y="98" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">缓冲 · 补传</text><text x="124" y="156" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">应用层</text><rect x="140" y="132" width="171" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="226" y="156" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">点位配置</text><rect x="323" y="132" width="171" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="408" y="156" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">遥测写入</text><rect x="506" y="132" width="171" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="591" y="156" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">规则评估</text><rect x="689" y="132" width="171" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="774" y="156" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">看板 · 曲线</text><text x="124" y="214" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">领域层</text><rect x="140" y="190" width="232" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="256" y="214" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">设备状态机 · 5 态</text><rect x="384" y="190" width="232" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="500" y="214" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">告警状态机 · 4 态</text><rect x="628" y="190" width="232" height="38" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="744" y="214" font-size="13" text-anchor="middle" fill="var(--vp-c-text-1)">点位 · 规则 · 通知</text>',31)])])),t[3]||(t[3]=d(`<p>实心高亮 = <strong>P0 已落地</strong>（接入 → 应用 → 领域）。现场层 PLC/仪表/AGV 仍是被采对象，不在本仓库里模拟硬件本体。三层职责不能混：接入层只管「读得到、不丢」，应用层只管「存得下、报得出」，领域层只管「状态对不对」。</p><h2 id="核心亮点" tabindex="-1">核心亮点 <a class="header-anchor" href="#核心亮点" aria-label="Permalink to “核心亮点”">​</a></h2><div class="sys-grid"><div class="sys-card"><div class="sys-card__icon">🔌</div><div class="sys-card__title">协议收敛</div><div class="sys-card__desc">MQTT 上报与 Modbus 轮询差异收进适配层，上层只认「设备 + 点位 + 值」</div></div><div class="sys-card"><div class="sys-card__icon">🧯</div><div class="sys-card__title">断线不丢数</div><div class="sys-card__desc">指数退避重连 + 本地环形缓冲，恢复后按时间序补传，缺口显式标记</div></div><div class="sys-card"><div class="sys-card__icon">🌊</div><div class="sys-card__title">高频写不压业务库</div><div class="sys-card__desc">攒批异步落库，明细 / 聚合分层保留，采集与写库解耦</div></div><div class="sys-card"><div class="sys-card__icon">🔔</div><div class="sys-card__title">告警不刷屏</div><div class="sys-card__desc">阈值 + 持续时长 + 迟滞恢复 + 窗口收敛，误报先死在规则里</div></div><div class="sys-card"><div class="sys-card__icon">⚡</div><div class="sys-card__title">最新值快查</div><div class="sys-card__desc">最新值走 Redis，历史曲线走范围聚合，看板不被慢查询拖白屏</div></div><div class="sys-card"><div class="sys-card__icon">🔁</div><div class="sys-card__title">双状态机</div><div class="sys-card__desc">设备 5 态、告警 4 态，非法流转统一 409 ILLEGAL_TRANSITION</div></div></div><h2 id="功能清单" tabindex="-1">功能清单 <a class="header-anchor" href="#功能清单" aria-label="Permalink to “功能清单”">​</a></h2><blockquote><p>状态图例：✅ 已实现 · 🔧 进行中 · 📋 待做</p></blockquote><h3 id="已实现-e2e-16-步全绿" tabindex="-1">已实现（E2E 16 步全绿） <a class="header-anchor" href="#已实现-e2e-16-步全绿" aria-label="Permalink to “已实现（E2E 16 步全绿）”">​</a></h3><table tabindex="0"><thead><tr><th>功能域</th><th>功能</th><th>状态</th><th>证据</th></tr></thead><tbody><tr><td>底座</td><td>多租户 / 权限 / 审计</td><td>✅ 复用</td><td><code>openbiz-saas-core</code>，表带 <code>tenant_id</code></td></tr><tr><td>底座</td><td>统一状态机 + 全局错误契约</td><td>✅ 复用</td><td><code>ILLEGAL_TRANSITION</code> → 409</td></tr><tr><td>设备</td><td>设备台账（编码 / 型号 / 位置）</td><td>✅</td><td><code>openbiz_iiot_device</code></td></tr><tr><td>设备</td><td>五态状态机</td><td>✅</td><td><code>OFFLINE/ONLINE/FAULT/MAINTENANCE/DECOMMISSIONED</code></td></tr><tr><td>告警</td><td>告警记录与四态状态机</td><td>✅</td><td><code>ACTIVE→ACKNOWLEDGED→RESOLVED</code> / <code>ACTIVE→CANCELLED</code></td></tr><tr><td>统计</td><td>设备 / 告警状态计数</td><td>✅</td><td><code>GET /api/iiot/stats</code></td></tr><tr><td>验证</td><td>HTTP E2E 脚本</td><td>✅</td><td><code>backend/e2e_iiot.py</code> · <code>E2E-RESULT.txt</code></td></tr></tbody></table><h3 id="p0-能力-已到「可连真设备演示」-约覆盖监控场景-60-70" tabindex="-1">P0 能力（已到「可连真设备演示」；约覆盖监控场景 60%～70%） <a class="header-anchor" href="#p0-能力-已到「可连真设备演示」-约覆盖监控场景-60-70" aria-label="Permalink to “P0 能力（已到「可连真设备演示」；约覆盖监控场景 60%～70%）”">​</a></h3><table tabindex="0"><thead><tr><th>功能域</th><th>功能</th><th>状态</th><th>说明</th></tr></thead><tbody><tr><td>协议</td><td>MQTT 接入（内嵌 broker / EMQX，QoS1）</td><td>✅</td><td>主题 <code>iiot/{tenantId}/{deviceCode}/telemetry</code> · P0-08</td></tr><tr><td>协议</td><td>Modbus TCP 轮询（寄存器 → 点位）</td><td>✅</td><td>内嵌从站 + 分组合并读 + 解码 · <code>verify_modbus.py</code> 15 PASS · P0-09；RTU 归 P1</td></tr><tr><td>点位</td><td>点位定义与配置</td><td>✅</td><td>设备 × 指标 × 数据类型 × 采集周期 · P0-04</td></tr><tr><td>时序</td><td>遥测写入（攒批 + 幂等）</td><td>✅</td><td>明细按天分区 · P0-05</td></tr><tr><td>时序</td><td>最新值缓存</td><td>✅</td><td>Redis Hash · P0-06</td></tr><tr><td>时序</td><td>范围查询与降采样</td><td>✅</td><td><code>interval</code> 驱动 min/max/avg · P0-07</td></tr><tr><td>监控</td><td>实时看板、趋势曲线</td><td>✅</td><td>状态灯 + 内联 SVG 曲线 + 活动告警 · P0-13</td></tr><tr><td>告警</td><td>阈值规则配置（持续时长 / 迟滞）</td><td>✅</td><td>规则可热更新 · P0-10</td></tr><tr><td>告警</td><td>分级 + 企业微信机器人通知</td><td>✅</td><td>outbox + 重试 · P0-11</td></tr><tr><td>协议</td><td>前端通用契约（<code>/list</code> · <code>/transition</code>）</td><td>✅</td><td>devices / alarms / points / rules</td></tr><tr><td>收尾</td><td>P0-15 E2E 扩展</td><td>✅</td><td><code>verify-p0-15.sh</code> → 原 16 步 + 契约 + 扩展 <strong>11 PASS</strong> 写入 <code>E2E-RESULT.txt</code>；用例 4/5（断库 / 20 万溢出）显式 SKIP</td></tr></tbody></table><h3 id="p1-p2-待做" tabindex="-1">P1 / P2 待做 <a class="header-anchor" href="#p1-p2-待做" aria-label="Permalink to “P1 / P2 待做”">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>功能</th><th>状态</th></tr></thead><tbody><tr><td>P1</td><td>向 MES 供数（<code>/api/iiot/v1</code> 集成层：HMAC 签名 / 幂等键 / 防重放、状态语义拆分、计数器差值、工单产量归属、下行写点位、事件推送、主数据对账）</td><td>✅</td></tr><tr><td>P1</td><td>Modbus RTU / S7 SoftPLC / OPC-UA Soft（P1-16）</td><td>✅</td></tr><tr><td>P1</td><td>边缘网关离线缓存、TDengine 时序库、告警升级与排班、能耗</td><td>📋</td></tr><tr><td>P1</td><td>OEE / 能耗分析</td><td>📋</td></tr><tr><td>P2</td><td>SCADA 组态、设备影子、远程指令 / OTA、预测性维护、万级点位、TLS 双向认证、行业测点模板</td><td>📋</td></tr></tbody></table><h2 id="核心流程" tabindex="-1">核心流程 <a class="header-anchor" href="#核心流程" aria-label="Permalink to “核心流程”">​</a></h2><p>一条数据从现场到看板，只有五个动作：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>设备 ─▶ 采集适配 ─▶ 归一化 ─▶ 攒批落库 ─▶ 规则评估 ─▶ 告警 / 通知</span></span>
<span class="line"><span>                        │                        │</span></span>
<span class="line"><span>                   Redis 最新值            看板 / 曲线查询</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>每一步对数据的副作用 —— 这是 IIoT 真正难的地方：</p><table tabindex="0"><thead><tr><th>环节</th><th>时序明细</th><th>Redis 最新值</th><th>告警</th><th>失败时怎么办</th></tr></thead><tbody><tr><td>采集（MQTT / Modbus）</td><td>—</td><td>—</td><td>—</td><td>进本地缓冲，标记 <code>gap</code></td></tr><tr><td>归一化</td><td>—</td><td>—</td><td>—</td><td>单位 / 类型不合法 → 丢弃并计数</td></tr><tr><td>攒批落库</td><td><code>INSERT</code> 一批</td><td><code>HSET</code> 覆盖</td><td>—</td><td>整批重试，幂等键去重</td></tr><tr><td>规则评估</td><td>只读窗口</td><td>只读</td><td>命中则建告警</td><td>跳过本轮，下轮重算</td></tr><tr><td>通知</td><td>—</td><td>—</td><td>写 outbox</td><td>重试 3 次后落死信</td></tr></tbody></table><p>三条不能破的约束：<strong>采集线程不写库</strong>（写慢不拖采集）、<strong>落库与规则解耦</strong>（规则挂不阻塞入库）、<strong>告警只由规则产生</strong>（不允许接口手工造 ACTIVE 告警绕过规则）。</p><h2 id="状态机" tabindex="-1">状态机 <a class="header-anchor" href="#状态机" aria-label="Permalink to “状态机”">​</a></h2><p><strong>设备</strong>（真实转移表，<code>Set.of()</code> 即终态）</p><table tabindex="0"><thead><tr><th>当前态</th><th>可转移到</th><th>触发</th></tr></thead><tbody><tr><td><code>OFFLINE</code></td><td><code>ONLINE</code> · <code>MAINTENANCE</code> · <code>DECOMMISSIONED</code></td><td>上线 / 检修 / 退役</td></tr><tr><td><code>ONLINE</code></td><td><code>FAULT</code> · <code>MAINTENANCE</code> · <code>OFFLINE</code> · <code>DECOMMISSIONED</code></td><td>故障 / 检修 / 掉线 / 退役</td></tr><tr><td><code>FAULT</code></td><td><code>OFFLINE</code> · <code>MAINTENANCE</code></td><td>恢复（回离线待上线）/ 检修</td></tr><tr><td><code>MAINTENANCE</code></td><td><code>OFFLINE</code></td><td>结束维护</td></tr><tr><td><code>DECOMMISSIONED</code></td><td>—</td><td>终态，不可再上线</td></tr></tbody></table><p><strong>告警</strong></p><table tabindex="0"><thead><tr><th>当前态</th><th>可转移到</th><th>触发</th></tr></thead><tbody><tr><td><code>ACTIVE</code></td><td><code>ACKNOWLEDGED</code> · <code>RESOLVED</code> · <code>CANCELLED</code></td><td>认领 / 自愈恢复 / 误报取消</td></tr><tr><td><code>ACKNOWLEDGED</code></td><td><code>RESOLVED</code></td><td>处理完成</td></tr><tr><td><code>RESOLVED</code> / <code>CANCELLED</code></td><td>—</td><td>终态</td></tr></tbody></table><p>关键接口（前缀 <code>/api/iiot</code>）：</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th><th>状态</th></tr></thead><tbody><tr><td>GET</td><td><code>/devices/list</code></td><td>设备分页列表（通用契约）</td><td>✅ 已实现 · 前端待切</td></tr><tr><td>POST</td><td><code>/devices/{id}/transition?to=ONLINE</code></td><td>状态流转统一入口</td><td>✅ 已实现 · 前端待切</td></tr><tr><td>POST</td><td><code>/devices/{id}/online</code> · <code>/fault</code> · <code>/recover</code> · <code>/offline</code> · <code>/maintenance</code> · <code>/end-maintenance</code> · <code>/decommission</code></td><td>动作式流转</td><td>✅</td></tr><tr><td>POST</td><td><code>/alarms/{id}/ack</code> · <code>/resolve</code> · <code>/cancel</code></td><td>告警流转</td><td>✅</td></tr><tr><td>GET</td><td><code>/points</code> · POST/PUT/DELETE</td><td>点位配置</td><td>✅</td></tr><tr><td>POST</td><td><code>/telemetry/ingest</code></td><td>内部采集入口（幂等，<code>X-Internal-Token</code>）</td><td>✅</td></tr><tr><td>GET</td><td><code>/telemetry/latest</code></td><td>最新值（读 Redis）</td><td>✅</td></tr><tr><td>GET</td><td><code>/telemetry/series</code></td><td>区间曲线（降采样）</td><td>✅</td></tr><tr><td>GET</td><td><code>/dashboard/overview</code></td><td>看板聚合（状态 + 活动告警 + 关键点位）</td><td>✅</td></tr><tr><td>GET</td><td><code>/stats</code></td><td>设备 / 告警状态计数</td><td>✅</td></tr></tbody></table><p>非法流转不写在 if-else 里：统一走 <code>StatusMachine</code> + <code>ILLEGAL_TRANSITION</code>，返回 409。与 <a href="./mes.html#状态机">MES 状态机</a>、<a href="./wms.html#单据状态机">WMS 单据状态机</a> 同一套做法。</p><h2 id="技术栈与架构" tabindex="-1">技术栈与架构 <a class="header-anchor" href="#技术栈与架构" aria-label="Permalink to “技术栈与架构”">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>技术</th><th>职责</th></tr></thead><tbody><tr><td>后端</td><td>Java 21 · Spring Boot 3 · MyBatis · Druid</td><td>REST、状态机、采集调度</td></tr><tr><td>采集</td><td>Eclipse Paho（MQTT）· 自研 Modbus TCP 主站/内嵌从站</td><td>订阅与轮询，收敛到同一 <code>Sample</code> / <code>IngestService</code></td></tr><tr><td>前端</td><td>Vite · Vue 3 · TypeScript · Element Plus · ECharts</td><td>元数据驱动（<code>modules.ts</code>）+ 看板</td></tr><tr><td>存储</td><td>MySQL 8（<code>openbiz_iiot</code>）</td><td>台账、点位、规则、遥测明细 / 聚合</td></tr><tr><td>缓存</td><td>Redis</td><td>最新值 Hash、规则缓存、分布式锁</td></tr><tr><td>消息</td><td>EMQX 5.x</td><td>设备上报入口，QoS1</td></tr><tr><td>底座</td><td>OpenBiz <code>saas-core</code> + RuoYi 登录外壳</td><td>多租户 / 权限 / 审计</td></tr></tbody></table>`,27)),(e(),a("svg",o,[...t[1]||(t[1]=[d('<rect x="0" y="0" width="880" height="292" rx="14" fill="var(--vp-c-bg-soft)"></rect><text x="124" y="38" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">接入</text><rect x="140" y="16" width="720" height="34" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="158" y="38" font-size="13" fill="var(--vp-c-text-1)">ingest/ · MQTT 订阅 · Modbus 轮询 · 归一化</text><text x="844" y="38" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">断线退避 · 本地缓冲</text><text x="124" y="84" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">接口</text><rect x="140" y="62" width="720" height="34" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="158" y="84" font-size="13" fill="var(--vp-c-text-1)">controller/ · REST + 内部采集入口</text><text x="844" y="84" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">租户 · 幂等 · 校验</text><text x="124" y="130" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">应用</text><rect x="140" y="108" width="720" height="34" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="158" y="130" font-size="13" fill="var(--vp-c-text-1)">application/ · 写入编排 · 查询编排 · 规则调度</text><text x="844" y="130" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">事务边界 · 攒批</text><text x="124" y="176" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">领域</text><rect x="140" y="154" width="720" height="34" rx="8" fill="var(--vp-c-brand-soft)" stroke="var(--vp-c-brand-1)"></rect><text x="158" y="176" font-size="13" fill="var(--vp-c-text-1)">domain/ · 设备 · 告警 · 点位 · 规则 · 状态机</text><text x="844" y="176" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">状态流转只在这里判定</text><text x="124" y="222" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">持久</text><rect x="140" y="200" width="720" height="34" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)"></rect><text x="158" y="222" font-size="13" fill="var(--vp-c-text-1)">mapper/ · MyBatis</text><text x="844" y="222" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">批量 INSERT · 分区查询</text><text x="124" y="268" font-size="12" font-weight="600" text-anchor="end" fill="var(--vp-c-text-2)">底座</text><rect x="140" y="246" width="720" height="34" rx="8" fill="var(--vp-c-bg)" stroke="var(--vp-c-divider)" stroke-dasharray="5 4"></rect><text x="158" y="268" font-size="13" fill="var(--vp-c-text-1)">openbiz-saas-core · 多租户 / 权限 / 审计</text><text x="844" y="268" font-size="12" text-anchor="end" fill="var(--vp-c-text-3)">MySQL openbiz_iiot · Redis</text>',25)])])),t[4]||(t[4]=d(`<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>openbiz-iiot-app/</span></span>
<span class="line"><span>├── backend/          # :18089</span></span>
<span class="line"><span>│   ├── src/main/java/com/openbiz/iiot/</span></span>
<span class="line"><span>│   │   ├── ingest/   #   P0 新增：mqtt / modbus / 归一化 / 缓冲</span></span>
<span class="line"><span>│   │   ├── domain/   #   设备 · 告警 · 点位 · 规则 · 状态机</span></span>
<span class="line"><span>│   │   ├── mapper/   #   MyBatis</span></span>
<span class="line"><span>│   │   ├── service/  #   编排</span></span>
<span class="line"><span>│   │   └── web/      #   控制器 · 全局异常</span></span>
<span class="line"><span>│   ├── e2e_iiot.py   #   HTTP E2E</span></span>
<span class="line"><span>│   └── E2E-RESULT.txt</span></span>
<span class="line"><span>├── frontend/         # Vue3/TS · modules.ts 元数据 · 看板</span></span>
<span class="line"><span>├── sql/              # 建表脚本（按版本递增）</span></span>
<span class="line"><span>└── README.md</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h2 id="核心数据模型" tabindex="-1">核心数据模型 <a class="header-anchor" href="#核心数据模型" aria-label="Permalink to “核心数据模型”">​</a></h2><table tabindex="0"><thead><tr><th>域</th><th>表</th><th>谁写</th><th>关键约束</th></tr></thead><tbody><tr><td>设备</td><td><code>openbiz_iiot_device</code></td><td>设备 Service</td><td><code>uk_tenant_code(tenant_id, device_code)</code></td></tr><tr><td>告警</td><td><code>openbiz_iiot_alarm</code></td><td>告警 Service</td><td>状态只经状态机改</td></tr><tr><td>点位</td><td><code>openbiz_iiot_point</code></td><td>点位 Service</td><td><code>uk(tenant_id, device_id, metric)</code></td></tr><tr><td>遥测明细</td><td><code>openbiz_iiot_telemetry</code></td><td>采集写入器</td><td><code>uk(device_id, metric, ts)</code> 幂等，按天分区</td></tr><tr><td>遥测聚合</td><td><code>openbiz_iiot_telemetry_agg</code></td><td>聚合任务</td><td><code>uk(device_id, metric, bucket)</code>，5 分钟粒度</td></tr><tr><td>规则</td><td><code>openbiz_iiot_rule</code></td><td>规则 Service</td><td>变更后发事件刷新内存缓存</td></tr><tr><td>通知</td><td><code>openbiz_iiot_notify_outbox</code></td><td>通知派发器</td><td>状态机 <code>PENDING/SENT/DEAD</code>，重试 3 次</td></tr></tbody></table><p>四条硬约束，和 WMS 的「不可篡改流水」同性质，不是形容词：</p><ol><li><strong>遥测只 <code>INSERT</code></strong>：明细表不提供 update / delete，纠错靠补新点 + 缺口标记，不改历史。</li><li><strong>幂等键唯一</strong>：<code>(device_id, metric, ts)</code> 唯一索引，MQTT QoS1 重投与补传重复不产生重复行。</li><li><strong>最新值可重建</strong>：Redis 丢了不慌，<code>MAX(ts)</code> 回查一次即恢复；Redis 只是加速，不是数据源。</li><li><strong>聚合可重算</strong>：聚合表任意时间窗可删除重算，明细是唯一事实来源。</li></ol><p>保留策略（P0 固定值，P1 可配）：明细 7 天、5 分钟聚合 90 天、告警与状态变更长期保留。</p><h2 id="系统边界" tabindex="-1">系统边界 <a class="header-anchor" href="#系统边界" aria-label="Permalink to “系统边界”">​</a></h2><table tabindex="0"><thead><tr><th>协同</th><th>链路</th><th>方向</th></tr></thead><tbody><tr><td>MES</td><td>设备状态 / 产量 / 告警 → 进度、OEE、安灯（P1）</td><td>IIoT → MES</td></tr><tr><td>WMS</td><td>AGV / 立库状态 → 调度（P2）</td><td>IIoT → WMS</td></tr><tr><td>ERP</td><td>设备台账主数据（P1）</td><td>ERP → IIoT</td></tr></tbody></table><p>原则：IIoT <strong>只采集与告警</strong>，不承载生产工单或库存业务；各系统独立库、不共享表；同步 OpenAPI、异步 MQ 事件；<code>tenantId</code> 透传。</p><h2 id="路线与验收" tabindex="-1">路线与验收 <a class="header-anchor" href="#路线与验收" aria-label="Permalink to “路线与验收”">​</a></h2><ol><li><strong>阶段一（已达成）</strong>：设备 + 告警双状态机，证明 OpenBiz 可承载物联域</li><li><strong>阶段二（P0，已收口）</strong>：数据层与状态机已落地（P0-01 迁移幂等 / P0-02 状态机抽泛型）；采集链路打通「写入 → 缓存 → 查询」——点位配置、攒批幂等写入（10 线程 × 1000 条并发去重到 1000 行）、Redis 最新值与回填、区间降采样与断线缺口标记（P0-03 ~ P0-07，32 项断言全绿）；<strong>MQTT 接入与数据模拟器已通</strong>——报文解析做成纯函数单测穷举异常分支，订阅端按 60s TTL 缓存设备与点位元数据（否则 100 台设备 1Hz 就是每秒 300 次查库），模拟器支持「直写」与「发报文」双输出，后者能把 MQTT 链路整条自证（P0-08 + P0-14，34 项断言全绿）；<strong>规则引擎已跑通告警闭环</strong>——持续时长、迟滞恢复、收敛窗口三件套，判定用采集旁路喂进的内存时间窗口而不是每轮查库（「窗口内全部样本满足」用聚合值推不出来），命中后告警与通知 outbox 同事务落库（P0-10，30 项断言全绿）；<strong>通知派发已闭环</strong>——派发器只读 outbox，成功置 <code>SENT</code>、失败按 2 的幂退避重试、超限置 <code>DEAD</code> 并回写告警的通知状态，webhook 未配置时照常出队（用计数表达「主动放弃」，而不是让 <code>PENDING</code> 积压成一个假故障）（P0-11，25 项断言全绿）；<strong>长期运行的三件事也补上了</strong>——按天分区自动补建与过期清理（跨天不补就会全部落进 <code>MAXVALUE</code> 兜底分区，写入不报错但分区裁剪失效）、5 分钟聚合只写「已封口」的桶并用重算窗口吸收迟到数据、心跳判活按每台设备的采集周期算阈值（判活下限必须大于 <code>last_seen</code> 的 30 秒写库节流，否则正常上报的设备会被反复判离线，状态灯开始抖）（P0-12，38 项断言全绿）；<strong>看板把链路变成了看得见的东西</strong>——首屏一个接口返回状态灯、活动告警与关键点位最新值，曲线用内联 SVG 画而不是引图表库（8KB 的独立 chunk），降级判定看「数据有多旧」而不是「这次请求成没成」：请求失败但快照还新时继续显示旧数据，超过 15 秒才亮黄条，后端挂了也不白屏（P0-13，27 项接口断言 + 11 个降级单测全绿）。<strong>P0-09 Modbus TCP 已通</strong>（内嵌从站 + 分组合并读 + 解码，<code>verify_modbus.py</code> 15 PASS）。<strong>P0-15 E2E 扩展已通</strong>（2026-11-02，<code>verify-p0-15.sh</code> 一键全绿：Modbus 单测 + 双 E2E 回归 + 扩展 11 PASS / 2 SKIP）。<strong>至此 P0-01 ~ P0-15 全部落地</strong>；用例 4/5（断库补传、20 万条溢出压测）需故障注入，在一键脚本里显式 SKIP、不伪装通过。</li></ol><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li>模块总览：<a href="/my-vitepress-site/instances/industrial/">02 工业数字化应用</a></li><li>同套件：<a href="./mes.html">MES</a> · <a href="./wms.html">WMS</a></li><li>实施设计：见工程仓库 <code>openbiz-iiot-app/docs/iiot-p0-design.md</code>（不对外发布）</li><li>实践文：<a href="/my-vitepress-site/apps/industrial/plc-collect.html">PLC 数据采集</a> · <a href="/my-vitepress-site/apps/industrial/device-monitor.html">设备监控与告警</a></li><li>实证页：<a href="/my-vitepress-site/apps/openbiz/iiot.html">OpenBiz › IIoT</a></li></ul><hr><p>上一级：<a href="/my-vitepress-site/instances/industrial/">02 工业数字化应用</a> · <a href="/my-vitepress-site/instances/">实例总览</a></p>`,15))])}const f=r(s,[["render",c]]);export{b as __pageData,f as default};
